			     "queryTransforms": [
			       {"op": "set", "name": "keep", "value": "1"},
			       ` + tc.badRule + `
			     ]}
			  ]
			}`
			// The request hits route 1; route 2 with the bad rule never matches.
			res := runResolveCLI(t, config, cliSuccessRequest)

